      "path": "src/mcp/gateway.ts",
      "content": "/**\n * dsh-skill-mcp-panel —— MCP 宿主服务（mcpManager）。\n */\nimport { TypertRemoteService } from \"@deepseek-ai/dsh-typert-protocol\";\nimport { fileURLToPath } from \"node:url\";\nimport { join, resolve } from \"node:path\";\nimport { resolveDshHome } from \"../host-paths.js\";\nimport { loadToolFilter, saveToolFilter } from \"../tool-filter.js\";\nimport {\n  authorizationHeader,\n  buildAuthorizationUrl,\n  createPkce,\n  discoverMetadataDetailed,\n  discoveryFailureMessage,\n  exchangeCode,\n  isExpired,\n  loadOAuthStore,\n  normalizeServerUrl,\n  registerClient,\n  removeOAuthRecord,\n  saveOAuthRecord,\n  startLoopbackServer\n} from \"../oauth.js\";\nimport {\n  MCP_PLUGIN_NAME,\n  isJsExprValue,\n  isManagedRow,\n  listMcpPatchRows,\n  readManagedBlock,\n  readMcpEntryText,\n  readPatchFile,\n  removeMcpEntry,\n  replaceMcpEntryText,\n  replaceMcpEntryWithRow,\n  setEntryDisabled,\n  writeManagedRows,\n  writeEvacuatedForeign,\n  type PatchRow\n} from \"../patch-editor.js\";\nimport {\n  applyServerEdit,\n  describeSchemaError,\n  inputFromPatchRow,\n  mcpServerInputSchema,\n  patchRowToView,\n  rowEnabled,\n  rowIdForServerName,\n  serverNameOfRow,\n  type McpServerInput\n} from \"./model.js\";\nimport {\n  mcpOAuthPollPayloadSchema,\n  mcpOAuthServerPayloadSchema,\n  mcpOAuthStartPayloadSchema,\n  mcpRawReadPayloadSchema,\n  mcpRawWritePayloadSchema,\n  mcpRemovePayloadSchema,\n  mcpSavePayloadSchema,\n  mcpSetEnabledPayloadSchema,\n  mcpTestPayloadSchema,\n  mcpToolsPayloadSchema,\n  mcpToolFilterPayloadSchema\n} from \"./wire.js\";\nimport { fiberPhaseOf, getLoaderEntry, mcpToolCount, waitForLoaderState } from \"./status.js\";\nimport { probeMcpServer } from \"./probe.js\";\n\n\nfunction stripUndefined(value: any): any {\n  if (Array.isArray(value)) return value.map((item) => stripUndefined(item));\n  if (value !== null && typeof value === \"object\") {\n    const out: Record<string, unknown> = {};\n    for (const [key, item] of Object.entries(value)) {\n      if (item === undefined) continue;\n      out[key] = stripUndefined(item);\n    }\n    return out;\n  }\n  return value;\n}\n\nconst MANAGED_ROW_IDS = new Set<string>();\n\n/**\n * 布尔 `disabled` 等 loader 跟上。`!!js` 由宿主求值，结果可以不是 true，\n * 再等 `disabled === true` 或等它变成启用都会空转到超时。\n * 这种行写完即结束，卡片仍按停用展示，表达式留在文件里。\n */\nasync function reconcileToggle(ctx: any, id: string | undefined, disabled: unknown): Promise<boolean> {\n  if (typeof id !== \"string\" || id === \"\") return false;\n  if (isJsExprValue(disabled)) return true;\n  return disabled === true\n    ? await waitForLoaderState(ctx, id, (entry) => entry !== undefined && entry.disabled === true)\n    : await waitForLoaderState(ctx, id, (entry) => entry !== undefined && entry.disabled !== true);\n}\n\n/**\n * handler 内校验 payload：失败抛「字段：原因」的中文错误。\n * 网关边界的 codec 是宽松 schema（见 wire.ts），校验必须在这里做，\n * 否则失败会退化成宿主那句泛化的 `failed boundary validation`。\n */\nfunction parseWirePayload(schema: { safeParse: (value: unknown) => any }, raw: unknown, label: string): any {\n  const result = schema.safeParse(raw);\n  if (result.success) return result.data;\n  throw new Error(label + \"：\" + describeSchemaError(result.error));\n}\n\n/** 进行中的 OAuth 登录流程（flowId → 流程状态）。一次登录一条，完成或失败即清理。 */\nconst OAUTH_FLOWS = new Map<string, any>();\n\nexport class McpManagerGateway extends TypertRemoteService {\n  toolFilter: any;\n\n  constructor(ctx: any, toolFilter?: any) {\n    super(ctx, \"mcpManager\");\n    this.toolFilter = toolFilter;\n  }\n\n  get C(): any {\n    return this.ctx as any;\n  }\n\n  patchPath(): string {\n    const base = this.C.baseUrl;\n    if (typeof base === \"string\" && base.length > 0) {\n      try {\n        const url = new URL(base);\n        if (url.protocol === \"file:\") return join(fileURLToPath(url), \"cordis.patch.yml\");\n      } catch {\n        // fall through to package-location fallback\n      }\n    }\n    const packageDir = fileURLToPath(new URL(\"../../\", import.meta.url));\n    return join(resolve(packageDir, \"../..\"), \"cordis.patch.yml\");\n  }\n\n  async readRows() {\n    const path = this.patchPath();\n    const raw = await readPatchFile(path);\n    // managed 仍是「受管块重写器认领的行」，只用于新建时追加。\n    // 启停 / 编辑 / 删除看 all：每一条 mcp-client 行，不论在不在块里。\n    const { managed, foreign } = readManagedBlock(raw);\n    const all = listMcpPatchRows(raw);\n    return { path, raw, managed, all, foreign };\n  }\n\n  serverNameOf(row: PatchRow): string | undefined {\n    return serverNameOfRow(row);\n  }\n\n  /**\n   * 按 payload 里的 serverName + entryId 定位唯一的 MCP 行。\n   *\n   * 同时给两个字段时按「都对上」匹配：文件里 id 重复（不同 serverName）或\n   * serverName 重复（不同 id）都能唯一定位到用户点的那一条；手写行没有 id\n   * 时只用 serverName。缺一个字段时退回单字段匹配，命中多条就报错。\n   */\n  resolveRow(rows: PatchRow[], ref: { serverName?: string; entryId?: string }): PatchRow {\n    const name = typeof ref.serverName === \"string\" && ref.serverName !== \"\" ? ref.serverName : undefined;\n    const entryId = typeof ref.entryId === \"string\" && ref.entryId !== \"\" ? ref.entryId : undefined;\n    const both = rows.filter(\n      (row) => (name === undefined || this.serverNameOf(row) === name) && (entryId === undefined || row.id === entryId)\n    );\n    if (both.length === 1) return both[0];\n    const label = name ?? entryId ?? \"\";\n    if (both.length > 1) {\n      throw new Error('MCP 行 \"' + label + '\" 在 cordis.patch.yml 里不唯一（id 或 serverName 重复）。'\n        + \"请用原文按 id 逐条修正，让每一行的 id 和 config.serverName 都唯一\");\n    }\n    if (name !== undefined) {\n      const byName = rows.filter((row) => this.serverNameOf(row) === name);\n      if (byName.length === 1) return byName[0];\n      if (byName.length > 1) {\n        throw new Error('serverName \"' + name + '\" 对应多条 MCP 行：请从卡片进入（面板会带上 entryId），'\n          + \"或在 CLI 里加 --id <entryId>；也可以直接改 cordis.patch.yml 消掉重名\");\n      }\n    }\n    if (entryId !== undefined) {\n      const byId = rows.filter((row) => row.id === entryId);\n      if (byId.length === 1) return byId[0];\n      if (byId.length > 1) throw new Error('id \"' + entryId + '\" 对应多条 MCP 行，请用原文按 id 逐条修正');\n    }\n    throw new Error('MCP 行 \"' + label + '\" 不存在');\n  }\n\n  /** 这一行的 patch-editor 定位器（id + serverName，缺 id 时只给 serverName）。 */\n  locatorOf(row: PatchRow): { id?: string; serverName?: string } {\n    return { id: typeof row.id === \"string\" ? row.id : undefined, serverName: this.serverNameOf(row) };\n  }\n\n  decorate(row: PatchRow, managed: boolean, entry: any, enabled: boolean) {\n    const view: any = patchRowToView(row);\n    if (view === undefined) return undefined;\n    const fiberPhase = fiberPhaseOf(entry?.fiber?.state);\n    return stripUndefined({\n      ...view,\n      enabled,\n      managed,\n      fiberPhase,\n      // 不按 enabled 归零：!!js 的 disabled 由宿主求值，行可能正在跑，显示真实工具数。\n      toolCount: mcpToolCount(this.C, view.serverName)\n    });\n  }\n\n  async list() {\n    let patch = { path: this.patchPath(), ok: false, error: null as string | null, foreign: [] as { id?: string; name?: string; managed: boolean }[] };\n    try {\n      const { path, all, foreign } = await this.readRows();\n      // 非 MCP 的外来行仍要报给界面（ADR-0003）。MCP 行已经在 servers 里，不再当成「未管理」。\n      const foreignEntries = foreign.entries.filter((entry) => entry.name !== MCP_PLUGIN_NAME);\n      patch = { path, ok: true, error: null, foreign: foreignEntries };\n      const servers: any[] = [];\n      for (const row of all) {\n        const entry = typeof row.id === \"string\" ? getLoaderEntry(this.C, row.id) : undefined;\n        const view = this.decorate(row, true, entry, rowEnabled(row));\n        if (view !== undefined) servers.push(view);\n      }\n      return { servers, externalServers: [], patch };\n    } catch (error) {\n      return { servers: [], externalServers: [], patch: { ...patch, error: error instanceof Error ? error.message : String(error) } };\n    }\n  }\n\n  findRowByServerName(rows: PatchRow[], serverName: string): PatchRow | undefined {\n    return rows.find((row) => this.serverNameOf(row) === serverName);\n  }\n\n  configInputFromRow(row: PatchRow): McpServerInput {\n    return inputFromPatchRow(row);\n  }\n\n  async save(rawPayload: unknown) {\n    const payload = parseWirePayload(mcpSavePayloadSchema, rawPayload, \"MCP 配置无效\");\n    const input = payload.input;\n    const { managed, all } = await this.readRows();\n    let previous: PatchRow | undefined;\n    if (payload.previousServerName !== undefined || payload.previousEntryId !== undefined) {\n      previous = this.resolveRow(all, { serverName: payload.previousServerName, entryId: payload.previousEntryId });\n    } else {\n      const same = all.filter((row) => this.serverNameOf(row) === input.serverName);\n      if (same.length > 1) {\n        throw new Error('serverName \"' + input.serverName + '\" 对应多条 MCP 行，可编辑的卡片带 entryId，请从卡片进入');\n      }\n      previous = same[0];\n    }\n    const previousName = previous !== undefined ? this.serverNameOf(previous) : undefined;\n    for (const row of all) {\n      if (row === previous) continue;\n      if (this.serverNameOf(row) !== input.serverName) continue;\n      // 编辑且没改名：文件里可能本来就有重名，允许保存（用 entryId 精确定位那一条）。\n      if (previous !== undefined && previousName === input.serverName) continue;\n      throw new Error('serverName \"' + input.serverName + '\" 已存在（' + String(row.id ?? \"未命名行\") + \"）\");\n    }\n    // !!js disabled 不是「未禁用」。卡片按停用展示，也不要等 loader 给出某个布尔值。\n    const enabled = previous !== undefined ? rowEnabled(previous) : payload.enabled;\n    const nextRow = applyServerEdit(previous, input, enabled);\n    const shownEnabled = rowEnabled(nextRow);\n    if (previous === undefined) {\n      if (all.some((row) => row.id === nextRow.id)) throw new Error('id \"' + String(nextRow.id) + '\" 已存在');\n      const nextRows = [...managed, nextRow];\n      nextRows.sort((a, b) => String(a.config?.serverName ?? \"\").localeCompare(String(b.config?.serverName ?? \"\")));\n      await writeManagedRows(this.patchPath(), nextRows);\n    } else {\n      await replaceMcpEntryWithRow(this.patchPath(), this.locatorOf(previous), nextRow);\n    }\n\n    const reconciled = await reconcileToggle(this.C, nextRow.id, nextRow.disabled);\n\n    const entry = typeof nextRow.id === \"string\" ? getLoaderEntry(this.C, nextRow.id) : undefined;\n    const server = this.decorate(nextRow, true, entry, shownEnabled);\n    if (server === undefined) throw new Error(\"写入成功但生成的 MCP 行无效\");\n    return { server, reconciled };\n  }\n\n  async removeServer(rawPayload: unknown) {\n    const payload = parseWirePayload(mcpRemovePayloadSchema, rawPayload, \"删除参数无效\");\n    const { all } = await this.readRows();\n    const row = this.resolveRow(all, { serverName: payload.serverName, entryId: payload.entryId });\n    await removeMcpEntry(this.patchPath(), this.locatorOf(row));\n    const reconciled = typeof row.id === \"string\"\n      ? await waitForLoaderState(this.C, row.id, (entry) => entry === undefined)\n      : false;\n    return { ok: true, reconciled };\n  }\n\n  async setEnabled(rawPayload: unknown) {\n    const payload = parseWirePayload(mcpSetEnabledPayloadSchema, rawPayload, \"启用参数无效\");\n    const { all } = await this.readRows();\n    const row = this.resolveRow(all, { serverName: payload.serverName, entryId: payload.entryId });\n    // 没有 id 的手写行也能开关：disabled 键按这一条自己的缩进插入/删除。\n    await setEntryDisabled(this.patchPath(), this.locatorOf(row), !payload.enabled);\n    const nextRow: PatchRow = { ...row };\n    if (payload.enabled) delete nextRow.disabled;\n    else nextRow.disabled = true;\n    const reconciled = await reconcileToggle(this.C, row.id, nextRow.disabled);\n    const entry = typeof row.id === \"string\" ? getLoaderEntry(this.C, row.id) : undefined;\n    const server = this.decorate(nextRow, true, entry, payload.enabled);\n    if (server === undefined) throw new Error(\"写入成功但生成的 MCP 行无效\");\n    return { server, reconciled };\n  }\n\n  /** 读出一条 MCP 行的原文，供面板的原文编辑框回填。 */\n  async readRaw(rawPayload: unknown) {\n    const payload = parseWirePayload(mcpRawReadPayloadSchema, rawPayload, \"原文参数无效\");\n    const { raw, all } = await this.readRows();\n    const row = this.resolveRow(all, { serverName: payload.serverName, entryId: payload.entryId });\n    return {\n      serverName: this.serverNameOf(row) ?? payload.serverName,\n      ...(typeof row.id === \"string\" ? { entryId: row.id } : {}),\n      text: readMcpEntryText(raw, this.locatorOf(row))\n    };\n  }\n\n  /** 用原文替换一条 MCP 行。表单未建模的字段就走这里。 */\n  async writeRaw(rawPayload: unknown) {\n    const payload = parseWirePayload(mcpRawWritePayloadSchema, rawPayload, \"原文参数无效\");\n    const { all } = await this.readRows();\n    const previous = this.resolveRow(all, { serverName: payload.serverName, entryId: payload.entryId });\n    const written = await replaceMcpEntryText(this.patchPath(), this.locatorOf(previous), payload.text);\n    const enabled = rowEnabled(written.row);\n    const reconciled = await reconcileToggle(this.C, written.row.id, written.row.disabled);\n    const entry = typeof written.row.id === \"string\" ? getLoaderEntry(this.C, written.row.id) : undefined;\n    const server = this.decorate(written.row, true, entry, enabled);\n    if (server === undefined) throw new Error(\"原文已写入，但生成的 MCP 行无效\");\n    return { server, reconciled };\n  }\n\n  async test(rawPayload: unknown) {\n    const payload = parseWirePayload(mcpTestPayloadSchema, rawPayload, \"测试参数无效\");\n    if (payload !== null && typeof payload === \"object\" && !(\"transport\" in payload) && \"serverName\" in payload) {\n      const { all } = await this.readRows();\n      const entryId = typeof (payload as any).entryId === \"string\" ? String((payload as any).entryId) : undefined;\n      const row = this.resolveRow(all, { serverName: String(payload.serverName), entryId });\n      return probeMcpServer(this.configInputFromRow(row));\n    }\n    return probeMcpServer(payload);\n  }\n\n  /**\n   * 某个 MCP 服务器当前注册的工具（公开名 `mcp__<serverName>__<原始名>`）。\n   * 只读工具注册表、不启动服务器：服务器还没连上时返回空列表，界面按「未连接」显示。\n   */\n  serverToolRows(serverName: string) {\n    const prefix = \"mcp__\" + serverName + \"__\";\n    const rows: any[] = [];\n    try {\n      const view = this.C.tools.view(undefined);\n      for (const name of view.knownNames ?? []) {\n        if (typeof name !== \"string\" || !name.startsWith(prefix)) continue;\n        const definition = typeof view.visible?.get === \"function\" ? view.visible.get(name) : undefined;\n        rows.push(stripUndefined({ name, description: typeof definition?.description === \"string\" ? definition.description : undefined }));\n      }\n    } catch {\n      // 工具注册表不可用：当作「一个都不知道」，界面显示未连接。\n    }\n    rows.sort((a, b) => a.name.localeCompare(b.name));\n    return rows;\n  }\n\n  dshHomeOf(): string {\n    return resolveDshHome();\n  }\n\n  /** 运行中控制器的禁用列表；还没挂上（或没有控制器）时返回 undefined，由调用方读盘。 */\n  liveDeny(): string[] | undefined {\n    const names = this.toolFilter?.denyOf?.();\n    return Array.isArray(names) ? [...names] : undefined;\n  }\n\n  /** 列出一个 MCP 服务器的工具，并标出其中已被禁用的（Issue #44）。 */\n  async listTools(rawPayload: unknown) {\n    const payload = parseWirePayload(mcpToolsPayloadSchema, rawPayload, \"工具查询参数无效\");\n    const tools = this.serverToolRows(payload.serverName);\n    const deny = this.liveDeny() ?? await loadToolFilter(this.dshHomeOf());\n    return {\n      serverName: payload.serverName,\n      tools,\n      disabled: deny.filter((name) => tools.some((row) => row.name === name)),\n      connected: tools.length > 0\n    };\n  }\n\n  /**\n   * 把受管块内**不属于面板**的顶层行原样搬到块外（#46 后续）。\n   * 只搬顶层行；块外内容、面板自己的行都不动，搬完语义与之前一致。\n   */\n  async evacuateForeign() {\n    const result = await writeEvacuatedForeign(this.patchPath());\n    return { moved: result.moved };\n  }\n\n  /** 读取单工具禁用列表。 */\n  async getToolFilter() {\n    const deny = this.liveDeny() ?? await loadToolFilter(this.dshHomeOf());\n    return { deny: [...deny].sort(), applied: this.appliedAgentCount() };\n  }\n\n  /** 写入单工具禁用列表并立刻重新施加到所有 agent（Issue #44）。 */\n  async setToolFilter(rawPayload: unknown) {\n    const payload = parseWirePayload(mcpToolFilterPayloadSchema, rawPayload, \"工具过滤参数无效\");\n    const deny: string[] = [\n      ...new Set<string>(payload.deny.filter((value: unknown): value is string => typeof value === \"string\" && value.startsWith(\"mcp__\")))\n    ].sort();\n    await saveToolFilter(this.dshHomeOf(), deny);\n    if (this.toolFilter !== undefined && typeof this.toolFilter.setDeny === \"function\") this.toolFilter.setDeny(deny);\n    return { deny, applied: this.appliedAgentCount() };\n  }\n\n  appliedAgentCount(): number {\n    return this.toolFilter !== undefined && typeof this.toolFilter.activeCount === \"function\" ? this.toolFilter.activeCount() : 0;\n  }\n\n  /** 找到某个服务器的 MCP 行（OAuth 要读写它的 headers）。 */\n  managedRow(rows: PatchRow[], serverName: string): PatchRow | undefined {\n    return rows.find((row) => this.serverNameOf(row) === serverName);\n  }\n\n  /** 把 Authorization 头写进那一行（其它 header、未建模字段、所在位置都保留）。 */\n  async writeAuthHeader(serverName: string, value: string | undefined) {\n    const { all } = await this.readRows();\n    const row = this.resolveRow(all, { serverName });\n    const config: any = { ...(row.config ?? {}) };\n    const headers = config.headers !== null && typeof config.headers === \"object\" && !Array.isArray(config.headers) ? { ...config.headers } : {};\n    if (value === undefined) delete headers.Authorization;\n    else headers.Authorization = value;\n    const nextConfig = { ...config };\n    if (Object.keys(headers).length === 0) delete nextConfig.headers;\n    else nextConfig.headers = headers;\n    await replaceMcpEntryWithRow(this.patchPath(), this.locatorOf(row), { ...row, config: nextConfig });\n  }\n\n  /**\n   * 开始一次 OAuth 登录（Issue #45 的面板入口）。\n   * 返回授权地址：前端交给浏览器打开，然后轮询 `oauthPoll`。\n   */\n  async oauthStart(rawPayload: unknown) {\n    const payload = parseWirePayload(mcpOAuthStartPayloadSchema, rawPayload, \"OAuth 参数无效\");\n    const { all } = await this.readRows();\n    const row = this.resolveRow(all, { serverName: payload.serverName });\n    if (row === undefined) throw new Error('MCP 行 \"' + payload.serverName + '\" 不存在');\n    const config: any = row.config ?? {};\n    if (config.transport !== \"streamable-http\" || typeof config.url !== \"string\" || config.url === \"\") {\n      throw new Error(\"只有 streamable-http 的服务器能用 OAuth 登录（stdio 由本地进程自己管凭据）\");\n    }\n    const discovery: any = await discoverMetadataDetailed(config.url);\n    const metadata = discovery.metadata;\n    if (metadata === undefined) throw new Error(discoveryFailureMessage(discovery.attempts));\n    const configuredUrl = normalizeServerUrl(config.url);\n    // PRM 声明的 resource 优先（同源才被 oauth.ts 接受）；没有就用配置里的 endpoint。\n    const serverUrl = typeof discovery.resource === \"string\" && discovery.resource !== \"\" ? discovery.resource : configuredUrl;\n    const state = Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2);\n    const { verifier, challenge } = createPkce();\n    const timeoutMs = Math.max(30, Math.min(900, Number(payload.timeoutSeconds ?? 300))) * 1000;\n    const loopback = await startLoopbackServer(state, timeoutMs);\n    const previous = (await loadOAuthStore(this.dshHomeOf()))[payload.serverName];\n    const clientId = payload.clientId ?? previous?.clientId ?? (await registerClient(metadata, loopback.redirectUri))?.client_id;\n    if (typeof clientId !== \"string\" || clientId === \"\") {\n      await loopback.close();\n      throw new Error(\"拿不到 client_id：服务器既不支持动态注册，也没有指定 clientId\");\n    }\n    const authUrl = buildAuthorizationUrl(metadata, clientId, loopback.redirectUri, challenge, state, payload.scope, serverUrl);\n    const flowId = Math.random().toString(36).slice(2) + Date.now().toString(36);\n    const flow: any = {\n      flowId,\n      serverName: payload.serverName,\n      state,\n      clientId,\n      metadata,\n      redirectUri: loopback.redirectUri,\n      verifier,\n      url: serverUrl,\n      status: \"pending\",\n      error: undefined,\n      startedAt: Date.now(),\n      loopback\n    };\n    OAUTH_FLOWS.set(flowId, flow);\n    // 后台等回调：失败也记在 flow 上、交给轮询回报，不在这里抛。\n    loopback.waitForCode().then(\n      (result: any) => {\n        flow.code = result.code;\n      },\n      (error: any) => {\n        flow.status = \"failed\";\n        flow.error = error instanceof Error ? error.message : String(error);\n      }\n    );\n    return { flowId, authUrl, redirectUri: loopback.redirectUri, expiresInSeconds: Math.round(timeoutMs / 1000) };\n  }\n\n  /** 轮询一次 OAuth 流程：pending / done / failed。拿到 code 就换令牌并落盘。 */\n  async oauthPoll(rawPayload: unknown) {\n    const payload = parseWirePayload(mcpOAuthPollPayloadSchema, rawPayload, \"OAuth 轮询参数无效\");\n    const flow = OAUTH_FLOWS.get(payload.flowId);\n    if (flow === undefined) throw new Error(\"这次登录流程不存在或已经结束，请重新点一次登录\");\n    if (flow.status === \"failed\") {\n      OAUTH_FLOWS.delete(payload.flowId);\n      await flow.loopback.close();\n      return { status: \"failed\", error: flow.error ?? \"授权失败\", serverName: flow.serverName };\n    }\n    if (flow.code === undefined) return { status: \"pending\", serverName: flow.serverName };\n    if (flow.status === \"done\") {\n      return { status: \"done\", serverName: flow.serverName, expiresAt: flow.expiresAt ?? null, header: flow.header ?? \"\" };\n    }\n    flow.status = \"exchanging\";\n    try {\n      const tokens = await exchangeCode(flow.metadata, flow.clientId, flow.code, flow.verifier, flow.redirectUri, flow.url);\n      await saveOAuthRecord(this.dshHomeOf(), flow.serverName, {\n        ...tokens,\n        clientId: flow.clientId,\n        serverUrl: flow.url,\n        tokenEndpoint: flow.metadata.token_endpoint\n      });\n      const header = authorizationHeader(tokens);\n      await this.writeAuthHeader(flow.serverName, header);\n      flow.status = \"done\";\n      flow.expiresAt = tokens.expiresAt;\n      flow.header = header;\n      await flow.loopback.close();\n      const row = this.managedRow((await this.readRows()).all, flow.serverName);\n      if (row !== undefined && typeof row.id === \"string\") await waitForLoaderState(this.C, row.id, (entry: any) => entry !== undefined);\n      return { status: \"done\", serverName: flow.serverName, expiresAt: flow.expiresAt ?? null, header };\n    } catch (error) {\n      flow.status = \"failed\";\n      flow.error = error instanceof Error ? error.message : String(error);\n      await flow.loopback.close();\n      OAUTH_FLOWS.delete(payload.flowId);\n      return { status: \"failed\", error: flow.error, serverName: flow.serverName };\n    }\n  }\n\n  /** 某个服务器当前的 OAuth 状态（给卡片显示）。 */\n  async oauthStatus(rawPayload: unknown) {\n    const payload = parseWirePayload(mcpOAuthServerPayloadSchema, rawPayload, \"OAuth 参数无效\");\n    const store = await loadOAuthStore(this.dshHomeOf());\n    const record = store[payload.serverName];\n    if (record === undefined) return { connected: false, headerReady: false, expiresAt: null, expired: false };\n    const { all } = await this.readRows();\n    const row = this.managedRow(all, payload.serverName);\n    const config: any = row?.config ?? {};\n    const headers = config.headers !== null && typeof config.headers === \"object\" && !Array.isArray(config.headers) ? config.headers : {};\n    return {\n      connected: typeof headers.Authorization === \"string\" && headers.Authorization.indexOf(\"Bearer \") === 0,\n      headerReady: typeof record.accessToken === \"string\",\n      expiresAt: typeof record.expiresAt === \"number\" ? record.expiresAt : null,\n      expired: isExpired(record)\n    };\n  }\n\n  /** 断开 OAuth：删掉 Authorization 头与本地令牌记录。 */\n  async oauthDisconnect(rawPayload: unknown) {\n    const payload = parseWirePayload(mcpOAuthServerPayloadSchema, rawPayload, \"OAuth 参数无效\");\n    await this.writeAuthHeader(payload.serverName, undefined);\n    await removeOAuthRecord(this.dshHomeOf(), payload.serverName);\n    const row = this.managedRow((await this.readRows()).all, payload.serverName);\n    if (row !== undefined && typeof row.id === \"string\") await waitForLoaderState(this.C, row.id, (entry: any) => entry !== undefined);\n    return { disconnected: true, serverName: payload.serverName };\n  }\n\n  reload() {\n    return this.list();\n  }\n}\n\n// 供 CLI 复用：判断一个 patch 行是否由面板管理。\nexport { MANAGED_ROW_IDS, isManagedRow, MCP_PLUGIN_NAME };\n"
    },
    {
      "path": "src/mcp/probe.ts",
      "content": "/**\n * dsh-skill-mcp-panel —— MCP 临时连接探针。\n *\n * 不写 patch、不注册 DSH 工具；Web“测试连接”与 `dsh-panel mcp test` 共用。\n */\nimport { Client } from \"@modelcontextprotocol/sdk/client/index.js\";\nimport { StdioClientTransport } from \"@modelcontextprotocol/sdk/client/stdio.js\";\nimport { StreamableHTTPClientTransport } from \"@modelcontextprotocol/sdk/client/streamableHttp.js\";\nimport { scrubbedParentEnv } from \"../host-paths.js\";\nimport { isJsExprValue } from \"../patch-editor.js\";\nimport { mcpServerInputSchema } from \"./model.js\";\nimport type { McpServerInput, WireScalar } from \"./model.js\";\n\nexport interface McpProbeTool {\n  name: string;\n  description?: string;\n}\n\nexport interface McpProbeResult {\n  ok: boolean;\n  tools: McpProbeTool[];\n  error?: string;\n}\n\nconst PROBE_TIMEOUT_MS = 15000;\n\n/**\n * 求值 !!js 表达式：与宿主 cordis 配置层的语义一致（with (ctx) { return eval(expr) }），\n * 区别只是测试连接跑在本进程、没有 loader 上下文。ctx 传空对象，表达式能拿到的\n * 全部来自全局（process.env 等）。\n */\nfunction evaluateJsExpr(expression: string): unknown {\n  return new Function(\"ctx\", \"expr\", \"with (ctx) { return eval(expr) }\")({}, expression);\n}\n\n/** 把单个配置值解析成真正的字符串：!!js 表达式在这里求值，失败给出可读原因。 */\nfunction resolveScalar(value: WireScalar | null | undefined, label: string): string | undefined {\n\tif (isJsExprValue(value)) {\n\t\tlet resolved: unknown;\n\t\ttry {\n\t\t\tresolved = evaluateJsExpr(value.__jsExpr);\n\t\t} catch (error) {\n\t\t\tthrow new Error(label + \" 的 !!js 表达式求值失败：\" + (error instanceof Error ? error.message : String(error)));\n\t\t}\n\t\tif (resolved === undefined || resolved === null) return undefined;\n\t\treturn typeof resolved === \"string\" ? resolved : String(resolved);\n\t}\n\treturn typeof value === \"string\" ? value : \"\";\n}\n\n/** 必需值：表达式求不出结果就直接报错（命令/参数/目录/地址缺了连不上）。 */\nfunction resolveRequired(value: WireScalar | null | undefined, label: string): string {\n\tconst resolved = resolveScalar(value, label);\n\tif (resolved === undefined) throw new Error(label + \" 的 !!js 表达式没有求值结果：\" + (isJsExprValue(value) ? value.__jsExpr : \"\"));\n\treturn resolved;\n}\n\n/** 环境变量/请求头：表达式求值为空时省略这个键，而不是把 undefined 发出去。 */\nfunction stringMap(value: Record<string, WireScalar | null> | undefined, label: string): Record<string, string> {\n\tconst out: Record<string, string> = {};\n\tfor (const [key, item] of Object.entries(value ?? {})) {\n\t\tif (item === null || item === undefined) continue;\n\t\tconst resolved = resolveScalar(item, label + \" \" + key);\n\t\tif (resolved === undefined) continue;\n\t\tout[key] = resolved;\n\t}\n  return out;\n}\n\nfunction createTransport(input: McpServerInput) {\n  if (input.transport === \"stdio\") {\n    return new StdioClientTransport({\n      command: resolveRequired(input.command, \"命令\"),\n      args: input.args.map((item) => resolveRequired(item, \"参数\")),\n      env: {\n        ...scrubbedParentEnv(),\n        ...stringMap(input.env, \"环境变量\")\n      },\n      cwd: input.cwd === \"\" || input.cwd === undefined ? undefined : resolveRequired(input.cwd, \"工作目录\")\n    });\n  }\n  return new StreamableHTTPClientTransport(new URL(resolveRequired(input.url, \"服务器地址\")), {\n    requestInit: { headers: stringMap(input.headers, \"请求头\") }\n  });\n}\n\nexport async function probeMcpServer(raw: unknown, timeoutMs = PROBE_TIMEOUT_MS): Promise<McpProbeResult> {\n  let input: McpServerInput;\n  try {\n    input = mcpServerInputSchema.parse(raw);\n  } catch (error) {\n    return { ok: false, tools: [], error: \"配置无效：\" + (error instanceof Error ? error.message : String(error)) };\n  }\n\n  const controller = new AbortController();\n  const timer = setTimeout(() => controller.abort(), timeoutMs);\n  const client = new Client({ name: \"dsh-skill-mcp-panel\", version: \"2.0.0\" });\n  let transport: StdioClientTransport | StreamableHTTPClientTransport | undefined;\n  try {\n    transport = createTransport(input);\n    await raceWithAbort(client.connect(transport), controller.signal);\n    const tools: McpProbeTool[] = [];\n    let cursor: string | undefined;\n    do {\n      const page = await client.listTools(cursor === undefined ? undefined : { cursor }, { signal: controller.signal });\n      for (const tool of page.tools) {\n        tools.push({\n          name: typeof tool.name === \"string\" ? tool.name : String(tool.name),\n          ...(typeof tool.description === \"string\" ? { description: tool.description } : {})\n        });\n      }\n      cursor = page.nextCursor;\n    } while (cursor !== undefined && cursor !== \"\");\n    return { ok: true, tools };\n  } catch (error) {\n    const reason = controller.signal.aborted ? \"连接测试超时（\" + timeoutMs + \"ms）\" : error instanceof Error ? error.message : String(error);\n    return { ok: false, tools: [], error: reason };\n  } finally {\n    clearTimeout(timer);\n    await Promise.allSettled([client.close().catch(() => {}), transport?.close().catch(() => {})]);\n  }\n}\n\nasync function raceWithAbort<T>(promise: Promise<T>, signal: AbortSignal): Promise<T> {\n  if (signal.aborted) return Promise.reject(new Error(\"aborted\"));\n  return new Promise<T>((resolvePromise, rejectPromise) => {\n    const onAbort = () => rejectPromise(new Error(\"aborted\"));\n    signal.addEventListener(\"abort\", onAbort, { once: true });\n    promise.then(\n      (value) => {\n        signal.removeEventListener(\"abort\", onAbort);\n        resolvePromise(value);\n      },\n      (error) => {\n        signal.removeEventListener(\"abort\", onAbort);\n        rejectPromise(error);\n      }\n    );\n  });\n}"
    },
    {
      "path": "src/patch-editor.ts",
      "content": "/**\n * dsh-skill-mcp-panel —— profile cordis.patch.yml 编辑器。\n *\n * 每一条 `@deepseek-ai/dsh-mcp-client` 行都归面板管（启停、表单编辑、删除、原文编辑），\n * 不再用受管块或 `panel-mcp-*` 前缀区分「受管 / 外部」。对这些行的改动都是就地拼接：\n * 只替换目标 entry 的字节跨度，文件其余部分逐字节保留。\n *\n * begin/end 受管块仍然是「面板新建的行」落点，也仍然是非 MCP 外来行的字节保真边界\n * （ADR-0003）：重写受管块时，块里不属于面板的非 MCP 条目原样搬回去。\n *\n * 写入使用同目录临时文件 + rename，并通过锁文件避免 Web 宿主与 CLI 并发写。\n */\nimport { open, readFile, rename, rm, stat, writeFile } from \"node:fs/promises\";\nimport { dirname, join } from \"node:path\";\nimport { isMap, isPair, isScalar, isSeq, parseDocument, stringify } from \"yaml\";\n\nexport const PANEL_MCP_BLOCK_BEGIN = \"# >>> dsh-skill-mcp-panel:mcp:begin\";\nexport const PANEL_MCP_BLOCK_END = \"# <<< dsh-skill-mcp-panel:mcp:end\";\nexport const MCP_PLUGIN_NAME = \"@deepseek-ai/dsh-mcp-client\";\nexport const MANAGED_ROW_ID_PREFIX = \"panel-mcp-\";\n\n/**\n * cordis 配置层的 !!js 标签：值是 JS 表达式，由宿主装载时求值\n * （@deepseek-ai/cordis-plugin-loader 的 interpolate → new Function + eval）。\n * DSH 官方给的环境变量写法就是它，例如：\n *   Authorization: !!js '`Bearer ${process.env.MCP_TOKEN}`'\n *\n * 面板必须原样往返这个标签：只把值当普通字符串读、再整块重写，表达式就会降级成\n * 字面量字符串——用户的令牌从此变成一个永远发不出去的值，而且没有任何提示。\n */\nconst JS_EXPR_TAG = \"tag:yaml.org,2002:js\";\n\n/** 表达式里的换行无法用单引号标量安全往返，退回双引号（JSON 转义）。 */\nfunction quoteJsExpr(expression: string): string {\n  if (/[\\n\\r]/.test(expression)) return JSON.stringify(expression);\n  return \"'\" + expression.replace(/'/g, \"''\") + \"'\";\n}\n\n/**\n * 自定义 !!js 标签：读时还原成 { __jsExpr } 标记对象（不再有 TAG_RESOLVE_FAILED），\n * 写时按原标签回写。identify 只认「恰好一个 __jsExpr 字符串键」的对象，\n * 不会误伤普通配置对象。\n */\nconst jsExprTag: any = {\n  tag: JS_EXPR_TAG,\n  resolve: (value: string) => ({ __jsExpr: value }),\n  identify: (value: unknown): boolean =>\n    value !== null &&\n    typeof value === \"object\" &&\n    Object.keys(value as Record<string, unknown>).length === 1 &&\n    typeof (value as { __jsExpr?: unknown }).__jsExpr === \"string\",\n  stringify: (node: any) => quoteJsExpr(String(node.value.__jsExpr))\n};\n\n/** 全部解析与序列化共用同一份标签定义，读到的 !!js 才能原样写回。 */\nconst YAML_CUSTOM_TAGS = [jsExprTag];\n\n/** !!js 表达式节点的标记形状。 */\nexport interface JsExprValue {\n  __jsExpr: string;\n}\n\n/** 判断一个 YAML 值是否是面板保留的 !!js 表达式节点。 */\nexport function isJsExprValue(value: unknown): value is JsExprValue {\n  return jsExprTag.identify(value);\n}\n\n/** Loader patch 行（宽松形状；受管块只包含 insert 列表）。 */\nexport interface PatchRow {\n  id?: string;\n  name?: string;\n  /**\n   * 布尔开关、`!!js` 表达式，或用户手写的其它值（`\"true\"`、`1`…）。\n   * 最后一种面板不解释：只在表单/原文保存时原样保留，绝不悄悄改成布尔。\n   */\n  disabled?: unknown;\n  config?: Record<string, unknown>;\n  [key: string]: unknown;\n}\n\nconst delay = (ms: number) => new Promise<void>((resolvePromise) => setTimeout(resolvePromise, ms));\n\n/** 读取 patch 文件；缺失/读失败统一带路径报错。 */\nexport async function readPatchFile(path: string): Promise<string> {\n  try {\n    return await readFile(path, \"utf8\");\n  } catch (error) {\n    throw new Error(\"无法读取 cordis.patch.yml（\" + path + \"）：\" + (error instanceof Error ? error.message : String(error)));\n  }\n}\n\n/** 校验整份 patch 文本：可解析且顶层是数组。不解出/写回任何值。 */\nexport function assertPatchText(raw: string): void {\n  const doc = parseDocument(raw, { logLevel: \"silent\", customTags: YAML_CUSTOM_TAGS });\n  if (doc.errors.length > 0) {\n    throw new Error(\"cordis.patch.yml 解析失败：\" + String(doc.errors[0]?.message ?? doc.errors[0]));\n  }\n  const parsed = doc.toJS();\n  if (!Array.isArray(parsed)) throw new Error(\"cordis.patch.yml 顶层必须是 YAML 数组\");\n}\n\n/** 校验整份 patch 文本：可解析且顶层是数组。不解出/写回任何值。 */\nexport async function validatePatchText(raw: string): Promise<void> {\n  assertPatchText(raw);\n}\n\n/** 把 YAML 解析出的单个条目收成 patch 行；`id`/`name` 都不是字符串的条目返回 undefined。 */\nfunction rowFromValue(value: unknown): PatchRow | undefined {\n  if (value === null || typeof value !== \"object\" || Array.isArray(value)) return undefined;\n  const row = value as Record<string, unknown>;\n  if (typeof row.id !== \"string\" && typeof row.name !== \"string\") return undefined;\n  const normalized: PatchRow = { ...row };\n  if (typeof row.id !== \"string\") delete normalized.id;\n  if (typeof row.name !== \"string\") delete normalized.name;\n  // disabled 一律原样留下：布尔是开关，!!js 是表达式，其它是用户手写的值。\n  // 丢掉它会让这条服务器在表单保存后变回启用。\n  if (row.disabled === undefined || row.disabled === null) delete normalized.disabled;\n  if (row.config === null || typeof row.config !== \"object\" || Array.isArray(row.config)) delete normalized.config;\n  return normalized;\n}\n\n/** 把 YAML 解析出的顶层条目拍平成 patch 行。 */\nfunction flattenPatchRows(entries: unknown): PatchRow[] {\n  const rows: PatchRow[] = [];\n  if (!Array.isArray(entries)) return rows;\n  for (const entry of entries) {\n    if (entry === null || typeof entry !== \"object\" || Array.isArray(entry)) continue;\n    const record = entry as Record<string, unknown>;\n    if (Array.isArray(record.insert)) {\n      for (const member of record.insert) {\n        const row = rowFromValue(member);\n        if (row !== undefined) rows.push(row);\n      }\n    } else {\n      const row = rowFromValue(record);\n      if (row !== undefined) rows.push(row);\n    }\n  }\n  return rows;\n}\n\n/**\n * 面板自己的行：`id` 以 `panel-mcp-` 开头。这是「面板拥有这一行」的唯一判据\n * （与行级操作 isManagedRow / findRowByServerName 一致）。\n *\n * 关键：判据只能看**这一行**。受管块里允许存在别的工具、旧版本或用户手写的\n * 条目，它们不是我们的，一律原样保留（见 ManagedBlockForeign）。\n */\nexport function isManagedRow(row: PatchRow): boolean {\n  return typeof row.id === \"string\" && row.id.startsWith(MANAGED_ROW_ID_PREFIX);\n}\n\n/**\n * 受管块里**不属于面板**的部分。面板必须原样保留它们：顶层的 `- id:` 条目是\n * 「按 id 定向覆盖」，`insert` 成员是「追加」——把前者折叠进 insert 会改掉语义，\n * 并让同一个 loader id 出现两行（dsh-market 的试算按 id 计数，直接判重复而回滚\n * 整批更新，见 ADR-0003）。\n */\nexport interface ManagedBlockForeign {\n  /** 外来顶层条目的原始文本（逐字节，含 `- ` 前缀与行尾换行）。 */\n  top: string;\n  /** 外来 `insert` 条目的原始文本（逐字节）。面板不认领放进外来 insert 里的行。 */\n  insert: string;\n  /** 外来部分里认出 id / name 的条目，供界面提示「块内还有哪些行不属于面板」。 */\n  entries: { id?: string; name?: string; managed: boolean }[];\n}\n\nconst EMPTY_FOREIGN: ManagedBlockForeign = { top: \"\", insert: \"\", entries: [] };\n\n/**\n * 受管块里每个顶层条目的完整文本跨度（含 `- ` 前缀、行尾换行、以及条目之间的注释）。\n *\n * 跨度按「下一个条目的行首」界定并**首尾相接铺满整块**（第一段从 0 开始，最后一段\n * 到块尾），而不是按节点自身的 range：嵌套块集合（如 `insert:` 下面的列表）的 range\n * 末尾不覆盖自己的内容，而注释与空行不属于任何节点。铺满之后块内每个字节都有着落，\n * 外来部分才能真正逐字节搬运。\n */\nfunction blockItemSpans(text: string, nodes: any[]): { start: number; end: number }[] {\n  const starts = nodes.map((node) => text.lastIndexOf(\"\\n\", node.range[0] - 1) + 1);\n  return nodes.map((_, index) => ({\n    start: index === 0 ? 0 : starts[index],\n    end: index + 1 < nodes.length ? starts[index + 1] : text.length\n  }));\n}\n\n/** 条目是不是 `insert:` 列表；是则返回成员节点。 */\nfunction insertMembers(node: any): any[] | undefined {\n  if (!isMap(node) || node.items.length !== 1) return undefined;\n  const pair = node.items[0];\n  const key = pair?.key as { value?: unknown } | undefined;\n  if (key === undefined || key === null || typeof key !== \"object\" || key.value !== \"insert\") return undefined;\n  return isSeq(pair.value) ? pair.value.items : undefined;\n}\n\n/**\n * 读受管块：面板自己的行 + 块内不属于面板的部分。\n * 无标记时返回空结果；标记不完整、块内容解析失败则抛错。\n */\nexport function readManagedBlock(raw: string): { managed: PatchRow[]; foreign: ManagedBlockForeign } {\n  const begin = raw.indexOf(PANEL_MCP_BLOCK_BEGIN);\n  const end = raw.indexOf(PANEL_MCP_BLOCK_END);\n  if (begin < 0 && end < 0) return { managed: [], foreign: EMPTY_FOREIGN };\n  if (begin < 0 || end < 0 || end < begin) throw new Error(\"cordis.patch.yml 中 dsh-skill-mcp-panel 受管块标记不完整（begin/end 必须成对）\");\n  const blockStart = raw.indexOf(\"\\n\", begin);\n  if (blockStart < 0) throw new Error(\"cordis.patch.yml 受管块格式损坏\");\n  const text = raw.slice(blockStart + 1, end);\n  const doc = parseDocument(text, { logLevel: \"silent\", customTags: YAML_CUSTOM_TAGS });\n  if (doc.errors.length > 0) throw new Error(\"受管块解析失败：\" + String(doc.errors[0]?.message ?? doc.errors[0]));\n  const parsed = doc.toJS();\n  if (!Array.isArray(parsed)) throw new Error(\"受管块内容必须是 YAML 数组\");\n\n  const managed: PatchRow[] = [];\n  const topParts: string[] = [];\n  const insertParts: string[] = [];\n  const entries: ManagedBlockForeign[\"entries\"] = [];\n  const nodes: any[] = isSeq(doc.contents) ? doc.contents.items : [];\n  const spans = blockItemSpans(text, nodes);\n  for (let index = 0; index < nodes.length; index++) {\n    const node = nodes[index];\n    const value: any = parsed[index];\n    const members = insertMembers(node);\n    if (members !== undefined) {\n      // 只有「成员全是面板行」的 insert 条目才归面板所有。混着外来成员的整条原样\n      // 保留——认领其中长得像面板行的那几条会同时触发重复写入。\n      const rows: (PatchRow | undefined)[] = (Array.isArray(value?.insert) ? value.insert : []).map(rowFromValue);\n      const owned = rows.length > 0 && rows.every((row) => row !== undefined && isManagedRow(row));\n      if (owned) {\n        for (const row of rows) managed.push(row as PatchRow);\n        continue;\n      }\n      for (const row of rows) if (row !== undefined) entries.push({ id: row.id, name: row.name, managed: isManagedRow(row) });\n      insertParts.push(text.slice(spans[index].start, spans[index].end));\n      continue;\n    }\n    const row = rowFromValue(value);\n    if (row !== undefined && isManagedRow(row)) {\n      managed.push(row);\n      continue;\n    }\n    if (row !== undefined) entries.push({ id: row.id, name: row.name, managed: false });\n    topParts.push(text.slice(spans[index].start, spans[index].end));\n  }\n  return { managed, foreign: { top: topParts.join(\"\"), insert: insertParts.join(\"\"), entries } };\n}\n\n/** 提取 begin/end 标记之间的受管行（只含面板自己的行）；无标记返回空数组。 */\nexport function extractManagedRows(raw: string): PatchRow[] {\n  return readManagedBlock(raw).managed;\n}\n\n/** 解析整份 patch 并返回其中所有 MCP 客户端行（不区分是否受管）。 */\nexport function listMcpPatchRows(raw: string): PatchRow[] {\n  const doc = parseDocument(raw, { logLevel: \"silent\", customTags: YAML_CUSTOM_TAGS });\n  if (doc.errors.length > 0) return [];\n  const parsed = doc.toJS();\n  if (!Array.isArray(parsed)) return [];\n  return flattenPatchRows(parsed).filter((row) => row.name === MCP_PLUGIN_NAME);\n}\n\n/**\n * 生成受管块文本（三部分都为空时返回空字符串）。\n *\n * 顺序：外来顶层条目 → 外来 insert 条目 → 面板自己的 `insert` 列表。外来部分逐字节\n * 原样搬运，面板只重建自己那一段。\n */\nexport function generateManagedBlock(rows: PatchRow[], foreign: ManagedBlockForeign = EMPTY_FOREIGN, baseIndent = \"\"): string {\n  const parts: string[] = [];\n  if (foreign.top !== \"\") parts.push(foreign.top.replace(/\\s*$/, \"\\n\"));\n  if (foreign.insert !== \"\") parts.push(foreign.insert.replace(/\\s*$/, \"\\n\"));\n  if (rows.length > 0) {\n    const body = stringify([{ insert: rows }], { indent: 2, lineWidth: 0, customTags: YAML_CUSTOM_TAGS });\n    parts.push(baseIndent === \"\" ? body : body.split(\"\\n\").map((line) => (line === \"\" ? line : baseIndent + line)).join(\"\\n\"));\n  }\n  if (parts.length === 0) return \"\";\n  return PANEL_MCP_BLOCK_BEGIN + \"\\n\" + parts.join(\"\") + PANEL_MCP_BLOCK_END + \"\\n\";\n}\n\n/** 块内顶层条目的基准缩进（正常是空字符串；整块被缩进时按原样对齐）。 */\nfunction blockBaseIndent(raw: string): string {\n  const begin = raw.indexOf(PANEL_MCP_BLOCK_BEGIN);\n  if (begin < 0) return \"\";\n  const end = raw.indexOf(PANEL_MCP_BLOCK_END);\n  const blockStart = raw.indexOf(\"\\n\", begin);\n  if (blockStart < 0) return \"\";\n  const text = raw.slice(blockStart + 1, end < 0 ? undefined : end);\n  for (const line of text.split(\"\\n\")) {\n    if (line.trim() === \"\" || line.trimStart().startsWith(\"#\")) continue;\n    if (!line.trimStart().startsWith(\"-\")) continue;\n    return /^[ \\t]*/.exec(line)?.[0] ?? \"\";\n  }\n  return \"\";\n}\n\n/**\n * 替换受管块；无标记且要写入行时追加到文件末尾。标记之外的所有字节原样保留，\n * 标记之内的**外来条目也原样保留**（不传 `foreign` 时自动从 `raw` 里读一遍）。\n */\nexport function replaceManagedBlock(raw: string, rows: PatchRow[], foreign?: ManagedBlockForeign): string {\n  const begin = raw.indexOf(PANEL_MCP_BLOCK_BEGIN);\n  const end = raw.indexOf(PANEL_MCP_BLOCK_END);\n  const foreignPart = foreign ?? (begin >= 0 || end >= 0 ? readManagedBlock(raw).foreign : EMPTY_FOREIGN);\n  const block = generateManagedBlock(rows, foreignPart, blockBaseIndent(raw));\n\n  if (begin >= 0 || end >= 0) {\n    if (begin < 0 || end < 0 || end < begin) throw new Error(\"cordis.patch.yml 中 dsh-skill-mcp-panel 受管块标记不完整（begin/end 必须成对）\");\n    const lineStart = raw.lastIndexOf(\"\\n\", begin - 1) + 1;\n    const afterEnd = raw.indexOf(\"\\n\", end);\n    const lineEnd = afterEnd < 0 ? raw.length : afterEnd + 1;\n    const next = raw.slice(0, lineStart) + block + raw.slice(lineEnd);\n    if (block !== \"\") return next;\n    // 删除最后一批受管行后，原文件可能只剩注释（或原先就是 `[]` 模板）；\n    // 此时必须补回流式空数组，否则 patch 文件不再是合法顶层数组。\n    const meaningful = next.split(/\\r?\\n/).map((line) => line.trim()).filter((line) => line !== \"\" && !line.startsWith(\"#\"));\n    if (meaningful.length === 0) return next.replace(/\\s*$/, \"\") + \"\\n[]\\n\";\n    return next;\n  }\n\n  if (block === \"\") return raw;\n  // 空 profile 模板是流式空数组 `[]`：直接追加块序列会变成 `[] - insert`，\n  // 必须在追加前把 `[]` 替换为受管块序列。\n  const lines = raw.split(/\\r?\\n/);\n  const meaningful = lines.map((line) => line.trim()).filter((line) => line !== \"\" && !line.startsWith(\"#\"));\n  if (meaningful.length === 1 && meaningful[0] === \"[]\") {\n    const index = raw.lastIndexOf(\"[]\");\n    return raw.slice(0, index) + block + raw.slice(index + 2);\n  }\n  const prefix = raw.length === 0 ? \"\" : raw.endsWith(\"\\n\") ? \"\\n\" : \"\\n\\n\";\n  return raw + prefix + block;\n}\n\n/** 同目录临时文件 + rename 原子写；Windows 上 rename 覆盖失败时退化为 rm+rename。 */\nexport async function writeFileAtomic(path: string, content: string): Promise<void> {\n  const temp = join(dirname(path), \".dsh-panel-tmp-\" + process.pid + \"-\" + Math.random().toString(36).slice(2, 8));\n  try {\n    await writeFile(temp, content, \"utf8\");\n    try {\n      await rename(temp, path);\n    } catch (error) {\n      if (error === null || typeof error !== \"object\" || ![\"EPERM\", \"EEXIST\", \"EACCES\"].includes((error as NodeJS.ErrnoException).code ?? \"\")) throw error;\n      await rm(path, { force: true });\n      await rename(temp, path);\n    }\n  } finally {\n    await rm(temp, { force: true }).catch(() => {});\n  }\n}\n\n/**\n * 以 `<path>.panel.lock` 为锁执行 fn。锁文件记录 pid + 时间；超过 30 秒视为\n * 陈旧锁自动清理。获取超时 5 秒。\n */\nexport async function withPatchLock<T>(path: string, fn: () => Promise<T> | T): Promise<T> {\n  const lockPath = path + \".panel.lock\";\n  const started = Date.now();\n  let handle: Awaited<ReturnType<typeof open>> | undefined;\n  while (handle === undefined) {\n    try {\n      handle = await open(lockPath, \"wx\");\n    } catch (error) {\n      if (error === null || typeof error !== \"object\" || (error as NodeJS.ErrnoException).code !== \"EEXIST\") throw error;\n      try {\n        const info = await stat(lockPath);\n        if (Date.now() - info.mtimeMs > 30000) await rm(lockPath, { force: true }).catch(() => {});\n      } catch {\n        // 锁在检查间隙被释放：继续重试。\n      }\n      if (Date.now() - started > 5000) throw new Error(\"等待 cordis.patch.yml 写锁超时（可能有其他 dsh-panel 进程正在写入）\");\n      await delay(50);\n    }\n  }\n  try {\n    await handle.writeFile(process.pid + \"\\n\" + Date.now() + \"\\n\", \"utf8\");\n    return await fn();\n  } finally {\n    await handle.close().catch(() => {});\n    await rm(lockPath, { force: true }).catch(() => {});\n  }\n}\n\n/**\n * 把受管块内的外来**顶层**条目原样搬到 begin 标记之前（仍在标记外，语义不变）。\n *\n * 背景：DSH 自己的配置编辑器（`dsh-config-editor`）在给某个插件首次写配置时，\n * 会往 patch 数组末尾 `document.add()` 一行；而我们的 end 注释正好是文件最后一行，\n * YAML 序列化时新行被排在尾注释之前，于是落进受管块里（Issue #46 的后续）。\n *\n * 只搬顶层行：`insert:` 里的外来成员搬出去会改变「插入哪些插件」的语义，留原样。\n * 异常输入（标记不成对、块被整体缩进、解析失败）一律原样返回，绝不半途改文件。\n */\nexport function evacuateForeignRows(raw: string): { raw: string; moved: number } {\n  const begin = raw.indexOf(PANEL_MCP_BLOCK_BEGIN);\n  const end = raw.indexOf(PANEL_MCP_BLOCK_END);\n  if (begin < 0 || end < 0) return { raw, moved: 0 };\n  // 整块被缩进时（嵌在别的结构里），搬出去会改变层级语义，宁可不做。\n  if (blockBaseIndent(raw) !== \"\") return { raw, moved: 0 };\n  let block;\n  try {\n    block = readManagedBlock(raw);\n  } catch {\n    return { raw, moved: 0 };\n  }\n  if (block.foreign.top === \"\") return { raw, moved: 0 };\n  // 只统计顶层条目：把 foreign.top 本身再解析一遍。\n  let moved = 0;\n  try {\n    const doc = parseDocument(block.foreign.top, { logLevel: \"silent\", customTags: YAML_CUSTOM_TAGS });\n    moved = isSeq(doc.contents) ? doc.contents.items.length : 0;\n  } catch {\n    return { raw, moved: 0 };\n  }\n  if (moved === 0) return { raw, moved: 0 };\n  const withoutTop = replaceManagedBlock(raw, block.managed, { ...block.foreign, top: \"\" });\n  const lineStart = withoutTop.lastIndexOf(\"\\n\", withoutTop.indexOf(PANEL_MCP_BLOCK_BEGIN) - 1) + 1;\n  const blockText = block.foreign.top.replace(/\\s*$/, \"\\n\");\n  return { raw: withoutTop.slice(0, lineStart) + blockText + withoutTop.slice(lineStart), moved };\n}\n\n/**\n * 读取 patch 文件、把受管块内的外来顶层条目搬出去、校验、加锁原子写回。\n * 返回搬走的条数与写回后的完整文本。\n */\nexport async function writeEvacuatedForeign(path: string): Promise<{ moved: number; raw: string }> {\n  return withPatchLock(path, async () => {\n    const raw = await readPatchFile(path);\n    const result = evacuateForeignRows(raw);\n    if (result.moved === 0) return { moved: 0, raw };\n    await validatePatchText(result.raw);\n    await writeFileAtomic(path, result.raw);\n    return { moved: result.moved, raw: result.raw };\n  });\n}\n\n/**\n * 读取 patch 文件、替换受管块、校验、加锁原子写回。\n * 返回写回后的完整文本。\n */\nexport async function writeManagedRows(path: string, rows: PatchRow[]): Promise<string> {\n  return withPatchLock(path, async () => {\n    const raw = await readPatchFile(path);\n    const next = replaceManagedBlock(raw, rows);\n    await validatePatchText(next);\n    await writeFileAtomic(path, next);\n    return next;\n  });\n}\n\n// ── 单条 MCP entry 的就地编辑（字节级）──────────────────────────────────────\n//\n// 启停、删除、原文替换、表单落盘都只动目标 entry 的文本跨度。loader 会热应用\n// `disabled` 的翻转（disabled → fiber.dispose()，删掉键 → entry.init()），\n// 所以就地改这一键就是热启停。!!js 表达式、注释、键序、未建模字段\n// （例如 maxInstructionBytes）在不改写它们的操作里逐字节保留。\n\n/** 定位一条 MCP 行：有 id 时按 id，否则按 config.serverName。 */\nexport interface McpEntryLocator {\n  id?: string;\n  serverName?: string;\n}\n\nconst SERVER_NAME_RE = /^[A-Za-z0-9_-]{1,32}$/;\n\n/** 取某个映射里指定标量键的 pair。 */\nfunction scalarPairOf(map: any, key: string): any | undefined {\n  for (const pair of map.items ?? []) {\n    if (!isPair(pair)) continue;\n    if (isScalar(pair.key) && pair.key.value === key) return pair;\n  }\n  return undefined;\n}\n\n/** entry 映射的 id 值（非标量返回 undefined）。 */\nfunction entryIdOfNode(map: any): string | undefined {\n  const pair = scalarPairOf(map, \"id\");\n  return pair !== undefined && isScalar(pair.value) && typeof pair.value.value === \"string\" ? pair.value.value : undefined;\n}\n\n/** entry 映射的 config.serverName（非字符串返回 undefined）。 */\nfunction serverNameOfNode(map: any): string | undefined {\n  const config = scalarPairOf(map, \"config\");\n  if (config === undefined || !isMap(config.value)) return undefined;\n  const name = scalarPairOf(config.value, \"serverName\");\n  return name !== undefined && isScalar(name.value) && typeof name.value.value === \"string\" ? name.value.value : undefined;\n}\n\n/** 映射的 name 标量是不是 MCP 客户端插件。 */\nfunction isMcpMap(map: any): boolean {\n  const pair = scalarPairOf(map, \"name\");\n  return pair !== undefined && isScalar(pair.value) && pair.value.value === MCP_PLUGIN_NAME;\n}\n\n/** pair 的行首位置：Pair 节点本身不带 range，以 key 标量的 range 为准。 */\nfunction pairStartOf(pair: any): number | undefined {\n  return isScalar(pair.key) && typeof pair.key.range?.[0] === \"number\" ? pair.key.range[0] : undefined;\n}\n\n/** pair 内容结束位置（value 末尾；无 value 时到 key 末尾）。 */\nfunction pairContentEndOf(pair: any): number | undefined {\n  if (pair?.value !== undefined && pair?.value !== null) {\n    const end = nodeContentEndOf(pair.value);\n    if (end !== undefined) return end;\n  }\n  return isScalar(pair?.key) && typeof pair.key.range?.[1] === \"number\" ? pair.key.range[1] : undefined;\n}\n\n/**\n * 节点**内容**的结束位置：最后一个标量/子节点的末尾。\n *\n * 不能用 `node.range[2]`：yaml 把条目后面的注释行算进节点的尾随范围，\n * 用它当跨度结尾会在替换/删除时把「下一条的说明注释」一起吞掉。\n */\nfunction nodeContentEndOf(node: any): number | undefined {\n  if (node === null || typeof node !== \"object\") return undefined;\n  if (isSeq(node)) {\n    const items: any[] = Array.isArray(node.items) ? node.items : [];\n    for (let index = items.length - 1; index >= 0; index -= 1) {\n      const end = nodeContentEndOf(items[index]);\n      if (end !== undefined) return end;\n    }\n    return typeof node.range?.[0] === \"number\" ? node.range[0] : undefined;\n  }\n  if (isMap(node)) {\n    const items: any[] = Array.isArray(node.items) ? node.items : [];\n    for (let index = items.length - 1; index >= 0; index -= 1) {\n      const end = pairContentEndOf(items[index]);\n      if (end !== undefined) return end;\n    }\n    return typeof node.range?.[0] === \"number\" ? node.range[0] : undefined;\n  }\n  if (typeof node.range?.[1] === \"number\") return node.range[1];\n  if (typeof node.range?.[2] === \"number\") return node.range[2];\n  return undefined;\n}\n\n/** index 处字符所在行的行首。 */\nfunction lineStartOf(text: string, index: number): number {\n  return text.lastIndexOf(\"\\n\", Math.max(0, index - 1)) + 1;\n}\n\n/** index 处字符所在行之后的位置（下一行行首；无换行则到文末）。 */\nfunction lineEndAfter(text: string, index: number): number {\n  const newline = text.indexOf(\"\\n\", index);\n  return newline < 0 ? text.length : newline + 1;\n}\n\n/** 文件用的换行符（新插入/重写的行跟随原文件，避免 CRLF 文件被掺进 LF 行）。 */\nfunction eolOf(text: string): string {\n  return text.includes(\"\\r\\n\") ? \"\\r\\n\" : \"\\n\";\n}\n\n/**\n * 序列条目的完整文本跨度：从所在行行首（含缩进与 `- `）到条目**内容**最后一行的行尾。\n * 条目后面的注释、空行不在跨度里，替换/删除时原样留下。\n */\nfunction itemSpan(raw: string, node: any): { start: number; end: number } {\n  const rangeStart = node?.range?.[0];\n  const contentEnd = nodeContentEndOf(node);\n  if (typeof rangeStart !== \"number\" || contentEnd === undefined) {\n    throw new Error(\"这条 MCP 行的 YAML 结构不支持就地编辑，请检查 cordis.patch.yml\");\n  }\n  return { start: lineStartOf(raw, rangeStart), end: lineEndAfter(raw, contentEnd) };\n}\n\ninterface FoundMcpEntry {\n  node: any;\n  /** 要替换 / 展示的序列条目（顶层行，或 insert 列表成员）。 */\n  item: any;\n  /** 是不是某个 `- insert:` 列表的成员（决定原文编辑能否改缩进/位置）。 */\n  inInsert: boolean;\n  /** insert 列表里只剩这一条时，删除应拿掉整个 `- insert:` 条目。 */\n  soleInsertItem?: any;\n}\n\n/** 收集整份 patch 里的 MCP 映射（顶层条目与 insert 成员）。 */\nfunction collectMcpEntries(doc: any): FoundMcpEntry[] {\n  const found: FoundMcpEntry[] = [];\n  if (!isSeq(doc.contents)) return found;\n  for (const item of doc.contents.items) {\n    if (!isMap(item)) continue;\n    const members = insertMembers(item);\n    if (members !== undefined) {\n      const mcpMembers = members.filter((member) => isMap(member) && isMcpMap(member));\n      for (const member of mcpMembers) {\n        found.push({\n          node: member,\n          item: member,\n          inInsert: true,\n          soleInsertItem: members.length === 1 ? item : undefined\n        });\n      }\n      continue;\n    }\n    if (isMcpMap(item)) found.push({ node: item, item, inInsert: false });\n  }\n  return found;\n}\n\nfunction parsePatchDocument(raw: string): any {\n  const doc = parseDocument(raw, { logLevel: \"silent\", customTags: YAML_CUSTOM_TAGS });\n  if (doc.errors.length > 0) {\n    throw new Error(\"cordis.patch.yml 解析失败：\" + String(doc.errors[0]?.message ?? doc.errors[0]));\n  }\n  return doc;\n}\n\n/**\n * 在整份 patch 里定位一条 MCP entry。\n *\n * 同时给了 id 和 serverName 时按「两个都对上」匹配——文件里 id 重复（不同\n * serverName）或 serverName 重复（不同 id）都能唯一定位到用户点的那一条。\n * 缺一个字段时退回单字段匹配；命中多条仍报错（提示用原文按 id 逐条修正）。\n */\nfunction findMcpEntry(raw: string, locator: McpEntryLocator): FoundMcpEntry {\n  const doc = parsePatchDocument(raw);\n  const all = collectMcpEntries(doc);\n  const id = typeof locator.id === \"string\" && locator.id !== \"\" ? locator.id : undefined;\n  const serverName = typeof locator.serverName === \"string\" && locator.serverName !== \"\" ? locator.serverName : undefined;\n  const byId = (entry: FoundMcpEntry) => (id === undefined ? true : entryIdOfNode(entry.node) === id);\n  const byName = (entry: FoundMcpEntry) => (serverName === undefined ? true : serverNameOfNode(entry.node) === serverName);\n  let hits = id !== undefined || serverName !== undefined ? all.filter((entry) => byId(entry) && byName(entry)) : [];\n  if (hits.length === 0 && id !== undefined) hits = all.filter(byId);\n  if (hits.length === 0 && serverName !== undefined) hits = all.filter(byName);\n  if (hits.length === 0) {\n    const label = id ?? serverName ?? \"\";\n    throw new Error('cordis.patch.yml 中找不到 MCP 行 \"' + label + '\"');\n  }\n  if (hits.length > 1) {\n    const label = serverName ?? id ?? \"\";\n    throw new Error(\n      'MCP 行 \"' + label + '\" 在 cordis.patch.yml 里不唯一（id 或 serverName 重复）。'\n      + \"请用原文按 id 逐条修正，让每一行的 id 和 config.serverName 都唯一\"\n    );\n  }\n  return hits[0];\n}\n\nfunction duplicateCounts(raw: string): { ids: Map<string, number>; names: Map<string, number> } {\n  const rows = listMcpPatchRows(raw);\n  const ids = new Map<string, number>();\n  const names = new Map<string, number>();\n  for (const row of rows) {\n    if (typeof row.id === \"string\" && row.id !== \"\") ids.set(row.id, (ids.get(row.id) ?? 0) + 1);\n    const name = typeof row.config?.serverName === \"string\" ? row.config.serverName : undefined;\n    if (name !== undefined && name !== \"\") names.set(name, (names.get(name) ?? 0) + 1);\n  }\n  return { ids, names };\n}\n\n/**\n * 写回一条时不许**新增**重复的 id / serverName。\n *\n * 文件里可能本来就有重名（手写配置），面板的职责是能帮用户一条条改掉，\n * 所以基线里已有的重复不算错；只有比写之前更多才拒绝。\n */\nfunction assertNoNewDuplicates(before: string, after: string): void {\n  const old = duplicateCounts(before);\n  const next = duplicateCounts(after);\n  for (const [id, count] of next.ids) {\n    if (count > 1 && count > (old.ids.get(id) ?? 0)) throw new Error('id \"' + id + '\" 在 cordis.patch.yml 里重复');\n  }\n  for (const [name, count] of next.names) {\n    if (count > 1 && count > (old.names.get(name) ?? 0)) throw new Error('serverName \"' + name + '\" 在 cordis.patch.yml 里重复');\n  }\n}\n\n/**\n * 删光 MCP 行后，空的受管块连同 begin/end 标记一起收掉，避免留下\n * 「只有一半标记」的文件（那会让后续所有写操作都被标记校验挡住）。\n * 块内的注释不丢：挪到原来的位置，作为普通注释留在文件里。\n */\nfunction stripEmptyManagedBlock(raw: string): string {\n  const begin = raw.indexOf(PANEL_MCP_BLOCK_BEGIN);\n  const end = raw.indexOf(PANEL_MCP_BLOCK_END);\n  if (begin < 0 || end < 0 || end < begin) return raw;\n  const bodyStart = raw.indexOf(\"\\n\", begin);\n  if (bodyStart < 0 || bodyStart > end) return raw;\n  const body = raw.slice(bodyStart + 1, lineStartOf(raw, end));\n  const meaningful = body.split(/\\r?\\n/).map((line) => line.trim()).filter((line) => line !== \"\" && !line.startsWith(\"#\"));\n  if (meaningful.length > 0) return raw;\n  const eol = eolOf(raw);\n  const comments = body.split(/\\r?\\n/).filter((line) => line.trim().startsWith(\"#\"));\n  const blockStart = lineStartOf(raw, begin);\n  const blockEnd = lineEndAfter(raw, end);\n  const kept = comments.length === 0 ? \"\" : comments.join(eol) + eol;\n  return raw.slice(0, blockStart) + kept + raw.slice(blockEnd);\n}\n\n/** 删除后若文件不再是数组、又只剩注释，补回 `[]`。 */\nfunction ensurePatchArray(raw: string): string {\n  try {\n    assertPatchText(raw);\n    return raw;\n  } catch (error) {\n    const meaningful = raw.split(/\\r?\\n/).map((line) => line.trim()).filter((line) => line !== \"\" && !line.startsWith(\"#\"));\n    if (meaningful.length === 0) return raw.replace(/\\s*$/, \"\") + \"\\n[]\\n\";\n    throw error;\n  }\n}\n\n/**\n * 就地翻转单个 entry 的 `disabled` 键，返回新文本；已是目标状态时原样返回。\n *\n *   停用：无键 → 在这一条最后一个键的下一行按同缩进插入 `disabled: true`；\n *         有键且值为 false → 原位把值改成 true；\n *   启用：有键且独占一行 → 整行删除；与别的内容同行 → 原位把值改成 false；\n *   disabled 值是 !!js 表达式 → 抛错让用户手动处理（绝不在表达式上动刀）。\n *\n * 没有 `id` 的行也能开关（插入位置按这一条自己的缩进算），不再要求补 id。\n * 只接受 @deepseek-ai/dsh-mcp-client 行，避免把别人的插件行关掉。\n */\nexport function setEntryDisabledInText(raw: string, locator: McpEntryLocator, disabled: boolean): string {\n  const found = findMcpEntry(raw, locator);\n  const map = found.node;\n  const label = String(locator.id ?? locator.serverName ?? \"\");\n  const namePair = scalarPairOf(map, \"name\");\n  const pluginName = namePair !== undefined && isScalar(namePair.value) ? namePair.value.value : undefined;\n  if (pluginName !== MCP_PLUGIN_NAME) {\n    throw new Error('entry \"' + label + '\" 不是 ' + MCP_PLUGIN_NAME + \" 行，面板只能开关 MCP 服务器\");\n  }\n  const eol = eolOf(raw);\n  const pair = scalarPairOf(map, \"disabled\");\n  const valueNode = pair?.value;\n  const valueStart = isScalar(valueNode) && typeof valueNode.range?.[0] === \"number\" ? valueNode.range[0] : undefined;\n  const valueEnd = isScalar(valueNode) && typeof valueNode.range?.[1] === \"number\" ? valueNode.range[1] : undefined;\n  const valueSource = valueStart !== undefined && valueEnd !== undefined\n    ? raw.slice(valueStart, valueEnd).trim()\n    : \"\";\n  // `!!js` 的标签在标量 range 之外（range 只覆盖表达式本身），所以既看节点标签，\n  // 也看 range 前紧挨着的原文。表达式绝不能被改写成 true/false。\n  const tagPrefix = valueStart !== undefined ? raw.slice(Math.max(0, valueStart - 80), valueStart) : \"\";\n  const jsExpr = isJsExprValue(isScalar(valueNode) ? valueNode.value : undefined)\n    || (isScalar(valueNode) && valueNode.tag === JS_EXPR_TAG)\n    || /(?:!!\\S+|!<[^>\\n]+>)\\s*$/.test(tagPrefix);\n  if (jsExpr || valueSource.startsWith(\"!!\")) {\n    throw new Error('entry \"' + label + '\" 的 disabled 是 !!js 表达式，请用原文编辑修改（面板不会改写表达式）');\n  }\n  if (disabled) {\n    if (pair !== undefined && valueSource === \"true\") return raw;\n    if (pair !== undefined) {\n      if (valueStart === undefined || valueEnd === undefined) {\n        throw new Error('entry \"' + label + '\" 的 disabled 写法不支持就地开关，请用原文编辑');\n      }\n      return raw.slice(0, valueStart) + \"true\" + raw.slice(valueEnd);\n    }\n    const pairs = (map.items ?? []).filter((item: any) => isPair(item));\n    const anchor = pairs.length > 0 ? pairs[pairs.length - 1] : undefined;\n    const anchorStart = anchor !== undefined ? pairStartOf(anchor) : undefined;\n    const anchorEnd = anchor !== undefined ? pairContentEndOf(anchor) : undefined;\n    if (anchorStart === undefined || anchorEnd === undefined) {\n      throw new Error('entry \"' + label + '\" 没有可插入 disabled 的位置，请用原文编辑');\n    }\n    const indent = \" \".repeat(Math.max(0, anchorStart - lineStartOf(raw, anchorStart)));\n    const insertion = indent + \"disabled: true\" + eol;\n    const position = lineEndAfter(raw, anchorEnd);\n    if (position >= raw.length) return raw + (raw.endsWith(\"\\n\") ? \"\" : eol) + insertion;\n    return raw.slice(0, position) + insertion + raw.slice(position);\n  }\n  if (pair === undefined || valueSource === \"false\") return raw;\n  const pairStart = pairStartOf(pair);\n  const pairEnd = pairContentEndOf(pair);\n  if (pairStart === undefined || pairEnd === undefined) {\n    throw new Error('entry \"' + label + '\" 的 disabled 写法不支持就地开关，请用原文编辑');\n  }\n  const pairLineStart = lineStartOf(raw, pairStart);\n  const pairLineEnd = lineEndAfter(raw, pairEnd);\n  const before = raw.slice(pairLineStart, pairStart);\n  const newlineAt = raw.indexOf(\"\\n\", pairEnd);\n  const after = raw.slice(pairEnd, newlineAt < 0 ? raw.length : newlineAt);\n  if (/^[ \\t\\r]*$/.test(before) && /^[ \\t\\r]*$/.test(after)) return raw.slice(0, pairLineStart) + raw.slice(pairLineEnd);\n  if (valueStart === undefined || valueEnd === undefined) {\n    throw new Error('entry \"' + label + '\" 的 disabled 写法不支持就地开关，请用原文编辑');\n  }\n  return raw.slice(0, valueStart) + \"false\" + raw.slice(valueEnd);\n}\n\n/**\n * 就地开关单条 MCP entry：读文件、翻转 `disabled`、校验、加锁原子写回。\n * 返回写回后的完整文本与是否真的改动（已是目标状态时不写盘）。\n */\nexport async function setEntryDisabled(path: string, locator: McpEntryLocator, disabled: boolean): Promise<{ raw: string; changed: boolean }> {\n  return withPatchLock(path, async () => {\n    const raw = await readPatchFile(path);\n    const next = setEntryDisabledInText(raw, locator, disabled);\n    if (next === raw) return { raw, changed: false };\n    await validatePatchText(next);\n    await writeFileAtomic(path, next);\n    return { raw: next, changed: true };\n  });\n}\n\n/** 读出一条 MCP entry 的原文（含缩进与 `- `，字节与文件中一致）。 */\nexport function readMcpEntryText(raw: string, locator: McpEntryLocator): string {\n  const found = findMcpEntry(raw, locator);\n  const span = itemSpan(raw, found.item);\n  return raw.slice(span.start, span.end);\n}\n\n/** 把用户提交的原文解析成一条 MCP 行；接受「一条序列」或「一个映射」。 */\nfunction rowFromEntrySnippet(text: string): PatchRow {\n  const doc = parseDocument(text, { logLevel: \"silent\", customTags: YAML_CUSTOM_TAGS });\n  if (doc.errors.length > 0) {\n    throw new Error(\"原文解析失败：\" + String(doc.errors[0]?.message ?? doc.errors[0]));\n  }\n  let value = doc.toJS();\n  if (Array.isArray(value)) {\n    if (value.length !== 1) throw new Error(\"原文只能包含一条 MCP 配置\");\n    value = value[0];\n  }\n  const row = rowFromValue(value);\n  if (row === undefined || row.name !== MCP_PLUGIN_NAME) {\n    throw new Error(\"原文必须仍是一条 \" + MCP_PLUGIN_NAME + \" 配置\");\n  }\n  // id 可以不写（手写行本来就可能没有 id）；写了就必须是非空字符串。\n  if (row.id !== undefined && (typeof row.id !== \"string\" || row.id.trim() === \"\")) {\n    throw new Error(\"原文里的 id 必须是非空字符串（不想写就整行删掉）\");\n  }\n  const serverName = row.config?.serverName;\n  if (typeof serverName !== \"string\" || !SERVER_NAME_RE.test(serverName)) {\n    throw new Error(\"config.serverName 必须是 1-32 位字母、数字、下划线或连字符\");\n  }\n  return row;\n}\n\n/**\n * 用用户提交的原文替换一条 MCP entry。跨度之外的字节不动。\n * 替换后整份文件仍须是合法 patch，且不能引出重复的 id / serverName；\n * 也不许借缩进把这一条搬出/搬进 `- insert:` 列表（append ↔ override 的语义会变）。\n */\nexport function replaceMcpEntryTextInText(raw: string, locator: McpEntryLocator, text: string): { raw: string; row: PatchRow } {\n  const found = findMcpEntry(raw, locator);\n  const span = itemSpan(raw, found.item);\n  const originalIndent = indentOfItem(raw, span.start);\n  const normalized = text.replace(/\\r\\n/g, \"\\n\");\n  const replacement = normalized.endsWith(\"\\n\") ? normalized : normalized + \"\\n\";\n  const row = rowFromEntrySnippet(replacement);\n  const before = listMcpPatchRows(raw).length;\n  const eol = eolOf(raw);\n  const fileText = eol === \"\\n\" ? replacement : replacement.replace(/\\n/g, eol);\n  const next = raw.slice(0, span.start) + fileText + raw.slice(span.end);\n  assertPatchText(next);\n  const afterRows = listMcpPatchRows(next);\n  if (afterRows.length !== before) throw new Error(\"原文只能改这一条 MCP 行，不能增删别的 entry\");\n  assertNoNewDuplicates(raw, next);\n  const serverName = typeof row.config?.serverName === \"string\" ? row.config.serverName : undefined;\n  const afterLocator: McpEntryLocator = typeof row.id === \"string\" ? { id: row.id, serverName } : { serverName };\n  let afterFound: FoundMcpEntry | undefined;\n  try {\n    afterFound = findMcpEntry(next, afterLocator);\n  } catch {\n    afterFound = undefined;\n  }\n  if (afterFound === undefined) {\n    throw new Error(\"原文写回后定位不到这一条 MCP 行：id 必须保留（或改成唯一值），且 serverName 不能与别的行重复\");\n  }\n  const afterIndent = indentOfItem(next, itemSpan(next, afterFound.item).start);\n  if (afterFound.inInsert !== found.inInsert || afterIndent !== originalIndent) {\n    throw new Error(\n      \"原文不能改变这一行的位置：请保留原来的缩进（\" + (originalIndent === \"\" ? \"顶层\" : \"「\" + originalIndent + \"」\")\n      + \"）和所在的列表（\" + (found.inInsert ? \"受管块 insert 成员\" : \"顶层条目\") + \"）\"\n    );\n  }\n  return { raw: next, row };\n}\n\n/** 读文件、替换一条 MCP entry 的原文、校验、加锁原子写回。 */\nexport async function replaceMcpEntryText(path: string, locator: McpEntryLocator, text: string): Promise<{ raw: string; row: PatchRow }> {\n  return withPatchLock(path, async () => {\n    const raw = await readPatchFile(path);\n    const next = replaceMcpEntryTextInText(raw, locator, text);\n    await writeFileAtomic(path, next.raw);\n    return next;\n  });\n}\n\n/** 序列条目所在行、`-` 之前的缩进。 */\nfunction indentOfItem(raw: string, start: number): string {\n  const lineEnd = raw.indexOf(\"\\n\", start);\n  const line = raw.slice(start, lineEnd < 0 ? raw.length : lineEnd);\n  return /^([ \\t]*)-/.exec(line)?.[1] ?? \"\";\n}\n\n/** 把一行 patch 序列化成与原条目同缩进、同换行符的列表项文本。 */\nfunction stringifyEntry(row: PatchRow, indent: string, eol = \"\\n\"): string {\n  const body = stringify([row], { indent: 2, lineWidth: 0, customTags: YAML_CUSTOM_TAGS });\n  const text = body.endsWith(\"\\n\") ? body : body + \"\\n\";\n  const normalized = eol === \"\\n\" ? text : text.replace(/\\n/g, eol);\n  if (indent === \"\") return normalized;\n  return normalized\n    .split(eol)\n    .map((line, index, all) => (line === \"\" && index === all.length - 1 ? \"\" : line === \"\" ? line : indent + line))\n    .join(eol);\n}\n\n/**\n * 用结构化行替换一条 MCP entry（表单保存、OAuth 写 Authorization）。\n * 只重写这一条；未知字段由调用方放进行对象后一起写回。跨度之外的字节不动。\n */\nexport function replaceMcpEntryWithRowInText(raw: string, locator: McpEntryLocator, row: PatchRow): string {\n  const found = findMcpEntry(raw, locator);\n  const span = itemSpan(raw, found.item);\n  const replacement = stringifyEntry(row, indentOfItem(raw, span.start), eolOf(raw));\n  const next = raw.slice(0, span.start) + replacement + raw.slice(span.end);\n  assertPatchText(next);\n  assertNoNewDuplicates(raw, next);\n  return next;\n}\n\n/** 读文件、用结构化行替换一条 MCP entry、校验、加锁原子写回。 */\nexport async function replaceMcpEntryWithRow(path: string, locator: McpEntryLocator, row: PatchRow): Promise<string> {\n  return withPatchLock(path, async () => {\n    const raw = await readPatchFile(path);\n    const next = replaceMcpEntryWithRowInText(raw, locator, row);\n    await writeFileAtomic(path, next);\n    return next;\n  });\n}\n\n/**\n * 就地删除一条 MCP entry。insert 列表里只剩它时，连同 `- insert:` 一起删除，\n * 避免留下空列表；受管块因此变空时收掉标记，让文件仍是合法顶层数组。\n */\nexport function removeMcpEntryInText(raw: string, locator: McpEntryLocator): string {\n  const found = findMcpEntry(raw, locator);\n  const target = found.soleInsertItem ?? found.item;\n  const span = itemSpan(raw, target);\n  const next = ensurePatchArray(stripEmptyManagedBlock(raw.slice(0, span.start) + raw.slice(span.end)));\n  assertPatchText(next);\n  return next;\n}\n\n/** 读文件、删除一条 MCP entry、校验、加锁原子写回。 */\nexport async function removeMcpEntry(path: string, locator: McpEntryLocator): Promise<string> {\n  return withPatchLock(path, async () => {\n    const raw = await readPatchFile(path);\n    const next = removeMcpEntryInText(raw, locator);\n    await writeFileAtomic(path, next);\n    return next;\n  });\n}"
